if (pm.response.code === 201) {
  const json = pm.response.json();
  pm.environment.set("post_id_2", json.data.id);

  pm.test("Aynı başlık slugı -2 veya sonraki ekle bitti", () => {
    const match = json.data.slug.match(
      /^node-js-ile-ilk-api-m-sifreleme-ve-guvenlik-(\d+)$/
    );
    pm.expect(match).to.not.equal(null);
    pm.expect(Number(match[1])).to.be.at.least(2);
    pm.expect(json.data.slug).to.not.equal(
      pm.environment.get("post_slug")
    );
  });
}

